-- Teams and folders.
--
-- Teams live here, not in Clerk: a team is a row in `teams` and its members
-- rows in `team_members` (Clerk user ids). The team's shared library has the
-- team's id — `org_…`, generated by the app — so everything keyed on
-- library_id (RLS, quotas, the purge) treats it like a personal one. The
-- two tables hold no document content and carry no RLS, like
-- terms_acceptance: the app reads a user's memberships before it has any
-- library scope to set.
--
-- Folders give a library the shape of a directory tree. A folder belongs to
-- one library for good, its parent is a folder of the same library, and a
-- document points at its folder with (folder_id, library_id) — so nothing
-- can ever point across libraries. A document without a folder sits at the
-- library's root. A folder is deleted only when empty (no ON DELETE action).

CREATE TABLE IF NOT EXISTS teams (
  id          text PRIMARY KEY CHECK (id ~ '^org_[A-Za-z0-9]+$'),
  name        text NOT NULL CHECK (length(name) BETWEEN 1 AND 80),
  pro         boolean NOT NULL DEFAULT false,            -- the team is on
  features    jsonb   NOT NULL DEFAULT '{}'::jsonb,      -- {files:false, zotero:false, ukaz:true}, as on an account
  quota_pages integer CHECK (quota_pages IS NULL OR quota_pages >= 1),
  created_at  timestamptz NOT NULL DEFAULT now(),
  created_by  text NOT NULL
);

CREATE TABLE IF NOT EXISTS team_members (
  team_id  text NOT NULL REFERENCES teams(id) ON DELETE CASCADE,
  user_id  text NOT NULL CHECK (user_id ~ '^user_[A-Za-z0-9]+$'),
  role     text NOT NULL CHECK (role IN ('admin', 'member')),
  added_at timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (team_id, user_id)
);
CREATE INDEX IF NOT EXISTS team_members_user ON team_members (user_id);

GRANT SELECT, INSERT, UPDATE, DELETE ON teams, team_members TO dawmain_app;

CREATE TABLE IF NOT EXISTS folders (
  id         uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  library_id text NOT NULL REFERENCES libraries(id) ON DELETE CASCADE,
  parent_id  uuid,
  name       text NOT NULL CHECK (length(name) BETWEEN 1 AND 80),
  created_by text NOT NULL CHECK (created_by ~ '^user_[A-Za-z0-9]+$'),
  created_at timestamptz NOT NULL DEFAULT now(),
  UNIQUE (id, library_id),
  CHECK (parent_id IS DISTINCT FROM id),
  FOREIGN KEY (parent_id, library_id) REFERENCES folders (id, library_id)
);
-- One name per place, whatever the case (the root counts as one place).
CREATE UNIQUE INDEX IF NOT EXISTS folders_name_uniq
  ON folders (library_id, coalesce(parent_id, '00000000-0000-0000-0000-000000000000'::uuid), lower(name));
CREATE INDEX IF NOT EXISTS folders_parent ON folders (library_id, parent_id);

ALTER TABLE documents ADD COLUMN IF NOT EXISTS folder_id uuid;
DO $$ BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'documents_folder_fk') THEN
    ALTER TABLE documents ADD CONSTRAINT documents_folder_fk
      FOREIGN KEY (folder_id, library_id) REFERENCES folders (id, library_id);
  END IF;
END $$;
CREATE INDEX IF NOT EXISTS documents_folder ON documents (library_id, folder_id);

ALTER TABLE folders ENABLE ROW LEVEL SECURITY;
ALTER TABLE folders FORCE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS library_scope ON folders;
CREATE POLICY library_scope ON folders USING (library_id = ANY (files_scope())) WITH CHECK (library_id = ANY (files_scope()));
DROP TRIGGER IF EXISTS freeze_library_id ON folders;
CREATE TRIGGER freeze_library_id BEFORE UPDATE ON folders FOR EACH ROW EXECUTE FUNCTION files_freeze_library_id();

GRANT SELECT, INSERT, UPDATE, DELETE ON folders TO dawmain_app;
